tpl = open('RULES.md', encoding='utf8').read()
out = []
for line in tpl.split('\n'):
    m = re.match(r'^(R[0-9a-z]+\.\d+) todo$', line)
    if m:
        k = m.group(1)
        if k not in A: raise SystemExit('missing ' + k)
        v = A[k]; out.append(f'{k} {v if v.split(":")[0] in ("pass", "n/a", "fix") else "pass: " + v}')
    else: out.append(line)
open('RULES.md', 'w', encoding='utf8').write('\n'.join(out))
print('RULES.md written')
